def sq(s):
    """Escape single quotes for SQL."""
    if s is None:
        return "NULL"
    return "'" + s.replace("'", "''") + "'"

def insert_cases(cases):
    sql = "DELETE FROM cases;\n"
    sql += "INSERT INTO cases (title, specialty, patient_age, patient_gender, chief_complaint, excerpt, history, examination, investigations, diagnosis, management, discussion, image_url, is_published, is_free) VALUES\n"
    rows = []
    for c in cases:
        vals = [
            sq(c["title"]), sq(c["specialty"]), "NULL", "NULL",
            sq(c["chief_complaint"]), sq(c["excerpt"]),
            sq(c["history"]), sq(c["examination"]),
            sq(c["investigations"]), sq(c["diagnosis"]),
            sq(c["management"]), sq(c["discussion"]),
            sq(c["image_url"]),
            "true" if c["is_published"] else "false",
            "true" if c["is_free"] else "false",
        ]
        rows.append("(" + ", ".join(vals) + ")")
    sql += ",\n".join(rows) + ";\n"
    with open("cases_insert.sql", "w") as f:
        f.write(sql)
    print(f"Generated SQL for {len(cases)} cases -> cases_insert.sql")

def c(title, spec, excerpt, history, exam, red, inv, guide, mgmt, rx, advice, chief=""):
    return {
        "title": title, "specialty": spec, "patient_age": None, "patient_gender": None,
        "chief_complaint": chief or title, "excerpt": excerpt,
        "history": "\n".join(history), "examination": "\n".join(exam),
        "investigations": "\n".join(inv),
        "diagnosis": None,
        "management": "\n".join(mgmt) + "\n\nPRESCRIPTION:\n" + "\n".join(rx),
        "discussion": "RED FLAGS / URGENT REFERRAL:\n" + "\n".join(red) + "\n\nGUIDELINE SUMMARY:\n" + guide + "\n\nPATIENT ADVICE & FOLLOW-UP:\n" + advice,
        "image_url": None, "is_published": True, "is_free": False
    }

